function validate([s]) {
  if (s.length < 1 || s.length > 50) return 's needs 1 to 50 events.';
  if (!/^[EL]+$/.test(s)) return "s may contain only 'E' and 'L'.";
  let inside = 0;
  for (const ch of s) {
    inside += ch === 'E' ? 1 : -1;
    if (inside < 0) return "Someone leaves an empty room: every 'L' needs an earlier 'E' still inside.";
  }
  return null;
}

