function minimumChairs(s) {
  // Try 0, 1, 2, ... chairs and replay the events until no arrival finds the room full.
  for (let count = 0; count <= s.length; count++) {
    let free = count;
    let fits = true;
    for (let i = 0; i < s.length && fits; i++) {
      if (s[i] === 'L') free += 1;
      else if (free === 0) fits = false;
      else free -= 1;
    }
    if (fits) return count;
  }
  return -1;
}

