function generate(rand, size) {
  const length = size === 'large' ? 50 : 1 + Math.floor(rand() * 10);
  const enterChance = 0.35 + rand() * 0.6;
  let s = '';
  let inside = 0;
  for (let i = 0; i < length; i++) {
    // Nobody can leave an empty room, so an empty room always gets an arrival.
    const enter = inside === 0 || rand() < enterChance;
    s += enter ? 'E' : 'L';
    inside += enter ? 1 : -1;
  }
  return [s];
}
